import {
  buildGraphTemplateComponents,
  countTemplateParameterSlots,
  isTemplateBuildFailure,
} from "../../waTemplateGraph.ts";
export { countTemplateParameterSlots };
import {
  buildWhatsAppTemplateComponents,
  interpolateDeliveryTemplate,
  type DeliveryContext,
  type WhatsAppTemplateParams,
} from "./buildDeliveryContext.ts";

type ParsedWhatsAppTemplateParams = {
  parameter_values?: string[];
  components_json?: unknown[];
  body?: string[];
  header?: string[];
  button?: string[];
};

function parseStoredWhatsAppTemplateParams(
  raw: Record<string, unknown> | null | undefined,
): ParsedWhatsAppTemplateParams {
  if (!raw || typeof raw !== "object") return {};
  const parameterValues = Array.isArray(raw.parameter_values)
    ? raw.parameter_values.map((v) => String(v ?? ""))
    : undefined;
  const componentsJson = Array.isArray(raw.components_json) ? raw.components_json : undefined;
  const body = Array.isArray(raw.body) ? raw.body.map((v) => String(v ?? "")) : undefined;
  const header = Array.isArray(raw.header) ? raw.header.map((v) => String(v ?? "")) : undefined;
  const button = Array.isArray(raw.button) ? raw.button.map((v) => String(v ?? "")) : undefined;
  return {
    parameter_values: parameterValues,
    components_json: componentsJson,
    body,
    header,
    button,
  };
}

export function validateWhatsAppTemplateParamsForPublish(
  params: Record<string, unknown> | null | undefined,
): string | null {
  const parsed = parseStoredWhatsAppTemplateParams(params);
  const components = parsed.components_json;
  const values = parsed.parameter_values;

  if (Array.isArray(components) && components.length > 0) {
    const expected = countTemplateParameterSlots(components);
    if (expected <= 0) return null;
    if (!Array.isArray(values)) {
      return `Template WhatsApp membutuhkan ${expected} variabel — mapping belum disimpan`;
    }
    if (values.length < expected) {
      return `Template WhatsApp membutuhkan ${expected} variabel, hanya ${values.length} yang diisi`;
    }
    const missing = values.slice(0, expected).some((v) => !String(v ?? "").trim());
    if (missing) return `Lengkapi semua ${expected} variabel template WhatsApp`;
    return null;
  }

  if (Array.isArray(parsed.body) && parsed.body.length > 0) {
    const missing = parsed.body.some((v) => !String(v ?? "").trim());
    if (missing) return "Lengkapi variabel template WhatsApp (format legacy)";
    return null;
  }

  return "Mapping variabel template WhatsApp wajib diisi";
}

/** Flat interpolated template values in Meta {{1}}…{{n}} order (for preview + persist). */
export function getInterpolatedLeadMagnetTemplateValues(
  params: Record<string, unknown> | null | undefined,
  ctx: DeliveryContext,
): string[] | null {
  const parsed = parseStoredWhatsAppTemplateParams(params);
  if (!Array.isArray(parsed.components_json) || parsed.components_json.length === 0) {
    return null;
  }
  const expected = countTemplateParameterSlots(parsed.components_json);
  const rawValues = parsed.parameter_values ?? [];
  if (rawValues.length < expected) return null;
  return rawValues
    .slice(0, expected)
    .map((v) => interpolateDeliveryTemplate(String(v ?? ""), ctx));
}

export function buildLeadMagnetWhatsAppComponents(
  params: Record<string, unknown> | null | undefined,
  ctx: DeliveryContext,
): { ok: true; components: Array<Record<string, unknown>> } | { ok: false; error: string } {
  const parsed = parseStoredWhatsAppTemplateParams(params);

  if (Array.isArray(parsed.components_json) && parsed.components_json.length > 0) {
    const expected = countTemplateParameterSlots(parsed.components_json);
    const rawValues = parsed.parameter_values ?? [];
    if (rawValues.length < expected) {
      return {
        ok: false,
        error: `Template expects ${expected} variable(s) but received ${rawValues.length}.`,
      };
    }
    const interpolated = rawValues
      .slice(0, expected)
      .map((v) => interpolateDeliveryTemplate(String(v ?? ""), ctx));
    const built = buildGraphTemplateComponents(parsed.components_json, interpolated);
    if (isTemplateBuildFailure(built)) {
      return { ok: false, error: built.reason };
    }
    return { ok: true, components: built.components };
  }

  const legacyParams: WhatsAppTemplateParams = {
    body: parsed.body,
    header: parsed.header,
    button: parsed.button,
  };
  return { ok: true, components: buildWhatsAppTemplateComponents(legacyParams, ctx) };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildDeliveryContext, interpolateDeliveryTemplate } from "./buildDeliveryContext.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

function formatResendFrom(displayName: string | undefined, fromEmail: string): string {
  const name = displayName?.trim() || "Synckerja";
  if (fromEmail.includes("<")) return fromEmail;
  return `${name} <${fromEmail}>`;
}

async function resolveOrgEmailFrom(
  admin: SupabaseClient,
  organizationId: string,
  campaignFromName: string | null | undefined,
): Promise<{ from: string; configured: boolean }> {
  const { data: org } = await admin
    .from("organizations")
    .select("lead_magnet_email_from, lead_magnet_email_from_name, name")
    .eq("id", organizationId)
    .maybeSingle();

  const orgFrom = String(org?.lead_magnet_email_from ?? "").trim();
  const envFrom = (Deno.env.get("RESEND_FROM_EMAIL") ?? "onboarding@resend.dev").trim();
  const fromEmail = orgFrom || envFrom;
  const displayName = campaignFromName?.trim()
    || String(org?.lead_magnet_email_from_name ?? "").trim()
    || String(org?.name ?? "").trim()
    || undefined;

  return {
    from: formatResendFrom(displayName, fromEmail),
    configured: Boolean(orgFrom || Deno.env.get("RESEND_FROM_EMAIL")),
  };
}

export async function deliverViaEmail(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    email: string;
  },
): Promise<{ ok: boolean; error?: string }> {
  const resendKey = Deno.env.get("RESEND_API_KEY");
  if (!resendKey) {
    return { ok: false, error: "RESEND_API_KEY is not configured" };
  }

  const to = args.email.trim().toLowerCase();
  if (!to.includes("@")) {
    return { ok: false, error: "Invalid recipient email" };
  }

  const ctx = await buildDeliveryContext(admin, {
    enrollment: args.enrollment,
    campaign: args.campaign,
  });

  const subjectTemplate = args.campaign.email_subject?.trim()
    || "Materi {{campaign_name}} — Synckerja";
  const htmlTemplate = args.campaign.email_html_body?.trim()
    || `<p>Hai {{username}},</p><p>Terima kasih! Berikut link materi kamu:</p><p><a href="{{delivery_url}}">{{delivery_url}}</a></p>`;

  const subject = interpolateDeliveryTemplate(subjectTemplate, ctx);
  const html = interpolateDeliveryTemplate(htmlTemplate, ctx);

  const { from } = await resolveOrgEmailFrom(
    admin,
    args.enrollment.organization_id,
    args.campaign.email_from_name,
  );

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${resendKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from,
      to: [to],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    console.error("[lead-magnet] Resend error", res.status, text);
    return { ok: false, error: text || "Resend request failed" };
  }
  return { ok: true };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

/** Instagram DM delivery with ≤3s hot-path target (sync before waitUntil). */
export async function deliverViaInstagramDm(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    isFallback?: boolean;
  },
): Promise<boolean> {
  const { sendDeliveryMessage } = await import("../followGateRuntime.ts");
  return sendDeliveryMessage(admin, {
    ...args,
    deliveryChannel: "instagram",
    isFallback: args.isFallback === true,
  });
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { persistLeadWhatsAppThread } from "../../omnichannelPublicApi/persistLeadWhatsAppThread.ts";
import { postTemplateMessage, renderTemplateBodyPreview } from "../../waTemplateGraph.ts";
import { buildDeliveryContext } from "./buildDeliveryContext.ts";
import {
  buildLeadMagnetWhatsAppComponents,
  getInterpolatedLeadMagnetTemplateValues,
} from "./buildLeadMagnetWhatsAppComponents.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

type WhatsAppCredentials = {
  whatsappAccountId: string;
  phoneNumberId: string;
  accessToken: string;
};

async function resolveWhatsAppCredentials(
  admin: SupabaseClient,
  organizationId: string,
  whatsappAccountId: string,
): Promise<WhatsAppCredentials | null> {
  const { data: waAccount } = await admin
    .from("organization_whatsapp_accounts")
    .select("id, phone_number_id, meta_access_token, is_active")
    .eq("id", whatsappAccountId)
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .maybeSingle();

  if (!waAccount?.phone_number_id) return null;

  let accessToken = String(waAccount.meta_access_token ?? "").trim();
  if (!accessToken) {
    const { data: orgMeta } = await admin
      .from("organization_meta_config")
      .select("meta_access_token")
      .eq("organization_id", organizationId)
      .maybeSingle();
    accessToken = String(orgMeta?.meta_access_token ?? "").trim();
  }
  if (!accessToken) return null;

  return {
    whatsappAccountId: String(waAccount.id),
    phoneNumberId: String(waAccount.phone_number_id),
    accessToken,
  };
}

export type DeliverViaWhatsAppTemplateResult =
  | {
      ok: true;
      waMessageId: string;
      conversationId?: string;
      persistError?: string;
      bodyParams: string[];
      rawMetadata: Record<string, unknown>;
    }
  | { ok: false; error: string };

export async function deliverViaWhatsAppTemplate(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    phoneDigits: string;
  },
): Promise<DeliverViaWhatsAppTemplateResult> {
  const accountId = args.campaign.whatsapp_account_id?.trim();
  const templateName = args.campaign.whatsapp_template_name?.trim();
  const templateLanguage = args.campaign.whatsapp_template_language?.trim() || "id";

  if (!accountId || !templateName) {
    return { ok: false, error: "WhatsApp template not configured on campaign" };
  }

  const creds = await resolveWhatsAppCredentials(admin, args.enrollment.organization_id, accountId);
  if (!creds) {
    return { ok: false, error: "WhatsApp account credentials not found" };
  }

  const ctx = await buildDeliveryContext(admin, {
    enrollment: args.enrollment,
    campaign: args.campaign,
  });
  const params = (args.campaign.whatsapp_template_params ?? {}) as Record<string, unknown>;
  const built = buildLeadMagnetWhatsAppComponents(params, ctx);
  if (!built.ok) {
    return { ok: false, error: built.error };
  }

  const bodyParams = getInterpolatedLeadMagnetTemplateValues(params, ctx) ?? [];
  const componentsJson = Array.isArray(params.components_json) ? params.components_json : [];
  const bodyPreview = componentsJson.length > 0
    ? renderTemplateBodyPreview(templateName, componentsJson, bodyParams)
    : `[Template: ${templateName}]`;

  const result = await postTemplateMessage(
    creds.phoneNumberId,
    creds.accessToken,
    args.phoneDigits,
    templateName,
    templateLanguage,
    built.components,
  );

  if (!result.ok) {
    return { ok: false, error: result.body ?? `WA send failed (${result.status})` };
  }

  let conversationId: string | undefined;
  let persistError: string | undefined;

  if (args.enrollment.lead_id) {
    const persisted = await persistLeadWhatsAppThread(admin, {
      organizationId: args.enrollment.organization_id,
      leadId: args.enrollment.lead_id,
      webId: "lead_magnet",
      phoneNumber: args.phoneDigits,
      customerName: args.enrollment.participant_username ?? "Lead",
      waMessageId: result.wa_message_id,
      templateName,
      templateLanguage,
      bodyPreview,
      bodyParams,
      rawMetadata: result.metaData,
      whatsappAccountId: creds.whatsappAccountId,
      phoneNumberId: creds.phoneNumberId,
      leadMagnetMeta: {
        enrollmentId: args.enrollment.id,
        campaignId: args.campaign.id,
      },
    });
    if (persisted.ok) {
      conversationId = persisted.conversationId;
    } else {
      persistError = persisted.error;
      console.error("[lead-magnet] persistLeadWhatsAppThread failed:", persisted.error);
    }
  } else {
    persistError = "Enrollment has no lead_id — livechat thread not created";
    console.warn("[lead-magnet] WA sent without lead_id on enrollment", args.enrollment.id);
  }

  return {
    ok: true,
    waMessageId: result.wa_message_id,
    conversationId,
    persistError,
    bodyParams,
    rawMetadata: result.metaData,
  };
}
